        "Jesse A. Livezey",
        "Cory Lorenz",
        "Jeremiah Lowin",
        "Qianli Ma",
        "Pierre-Antoine Manzagol",
        "Olivier Mastropietro",
        "Robert T. McGibbon",
        "Roland Memisevic",
        "Bart van Merrienboer",
        "Vincent Michalski",
        "Mehdi Mirza",
        "Alberto Orlandi",
        "Christopher Pal",
        "Razvan Pascanu",
        "Mohammad Pezeshki",
